{capture $c_11}
  {capture $c_10}
    {foreach ui_l($v_packs) as $v_pack}
      {capture $c_9}
        {capture $c_8}
          {capture $c_6}
            {if ui_t(ui_or([ui_get($v_pack, ['badge']), ui_and([!(ui_eq($v_item, 'row')), ui_gt(ui_count($v_packs, 'badge'), 0)])]))}
              {capture $c_2}
                {if ui_t(ui_get($v_pack, ['badge']))}
                  {capture $c_1}
                    {=ui_text(ui_at($v_badges, ui_get($v_pack, ['badge'])))}
                  {/capture}
                  {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'default', 'Size' => 'default', 'Class' => 'w-fit shrink-0', 'Attrs' => ui_attrs(['data-testid', 'badge'])], 'children' => $c_1])|noescape}
                {/if}
              {/capture}
              {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'flex min-h-6 items-center', 'Attrs' => ui_attrs(['data-slot', 'badge-slot'])], 'children' => $c_2])|noescape}
            {/if}
            {capture $c_5}
              {capture $c_3}
                {=ui_text(ui_get($v_pack, ['name']))}
              {/capture}
              {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'xl', 'Weight' => 'bold'], 'children' => $c_3])|noescape}
              {capture $c_4}
                {=ui_text(ui_money(ui_get($v_pack, ['price']), ui_get($v_pack, ['currency'])))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => '2xl', 'Weight' => 'bold'], 'children' => $c_4])|noescape}
            {/capture}
            {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '0', 'Class' => 'min-w-0'], 'children' => $c_5])|noescape}
          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Align' => 'start', 'Class' => ui_s(ui_cnv(['min-w-0', (ui_t(ui_eq($v_item, 'row')) ? 'flex-1' : '')]))], 'children' => $c_6])|noescape}
          {capture $c_7}
            {=ui_text($v_buy)}
          {/capture}
          {=ui_include('ui/button/button.latte', ['p' => ['Variant' => ui_s((ui_t(ui_eq(ui_get($v_pack, ['badge']), 'popular')) ? 'default' : 'outline')), 'Size' => 'sm', 'Type' => 'button', 'Class' => ui_s(ui_cnv(['w-fit shrink-0', (ui_t(ui_eq($v_item, 'row')) ? '' : 'mt-auto')])), 'Attrs' => ui_attrs(['data-testid', 'buy'])], 'children' => $c_7])|noescape}
        {/capture}
        {=ui_include('ui/card/card-content.latte', ['p' => ['Class' => ui_s(ui_cnv(['flex h-full gap-4', (ui_t(ui_eq($v_item, 'row')) ? 'flex-row flex-wrap items-center justify-between' : 'flex-col')]))], 'children' => $c_8])|noescape}
      {/capture}
      {=ui_include('ui/card/card.latte', ['p' => ['Variant' => 'default', 'Class' => ui_s(ui_cnv(['h-full', (ui_t(ui_eq($v_item, 'row')) ? 'gap-4 p-4' : (ui_t(ui_eq($v_density, 'compact')) ? 'gap-4 p-4' : ''))])), 'Attrs' => ui_attrs(['data-testid', 'item', 'data-badge', ui_get($v_pack, ['badge'])])], 'children' => $c_9])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_item, 'row')) ? '1' : ui_fit_cols((ui_t(ui_eq($v_cols, '2')) ? '1-2' : '1-4'), ui_len($v_packs)))), 'Class' => 'gap-4', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_10])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'measure' => (ui_t(ui_eq($v_item, 'row')) ? '2xl' : 'default'), 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_11])|noescape}
